// png-squeeze v2 — lossless PNG re-encoder for make.fun png-squeeze-01-run-20261127.
//
// Written from the competition spec (RULES.txt) and the v2 plan: the same colour-type
// forms and filter families as a plain PNG optimiser (palette / grey / RGB / RGBA,
// tRNS where a palette needs transparency), filter candidates ranked by real zlib
// level-6 size with the winner among the top 3 decided by zlib level-9 size, and
// the winning stream compressed with a vendored Zopfli (WASM, Apache-2.0,
// @gfx/zopfli 1.0.15) for the smallest streams, zlib level 9 for the rest. Which
// streams get Zopfli is decided purely from filtered-stream sizes (smallest first,
// cumulative cap), never from the wall clock, so two executions write identical
// bytes.
//
// Usage: node main.ts — reads /input/<id>/image.png (or $MAKEFUN_INPUT_DIR),
// writes /output/<id>/image.png (or $MAKEFUN_OUTPUT_DIR). Node 22, builtins only.
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { deflateSync, inflateSync } from 'node:zlib';

// ---------------------------------------------------------------------------
// Zopfli (WASM). The binary below is the @gfx/zopfli 1.0.15 WebAssembly module
// (Apache-2.0, https://github.com/gfx/universal-zopfli-js), base64. The loader
// around it is written here: it builds the tiny import object the module needs
// (memory, table, memcpy, heap growth, no-op fd/exit stubs), instantiates it,
// and exposes a zlib-format compress with 1 iteration and block splitting.
// ---------------------------------------------------------------------------
const ZOPFLI_WASM_B64 = '';

const ZOPFLI_BUDGET_BYTES = 13_000_000; // cumulative filtered size given to Zopfli
const ZOPFLI_ITERATIONS = 1;
const ZOPFLI_BLOCKSPLITTING_MAX = 5;

let zopfli: ((input: Uint8Array) => Buffer) | null = null;

async function initZopfli(): Promise<void> {
  if (zopfli !== null) return;
  try {
    const wasmBytes = Buffer.from(ZOPFLI_WASM_B64, 'base64');
    const PAGE = 65536;
    const memory = new WebAssembly.Memory({ initial: 256, maximum: 32768 });
    const table = new WebAssembly.Table({ initial: 8, maximum: 8, element: 'anyfunc' });
    let heapU8 = new Uint8Array(memory.buffer);
    let heap32 = new Int32Array(memory.buffer);
    const refreshViews = (): void => {
      heapU8 = new Uint8Array(memory.buffer);
      heap32 = new Int32Array(memory.buffer);
    };
    // Grow the heap the way Emscripten's _emscripten_resize_heap does.
    const resizeHeap = (requestedSize: number): number => {
      const oldSize = heapU8.length;
      const maxHeapSize = 2147483648;
      if (requestedSize > maxHeapSize) return 0;
      const minHeapSize = 16777216;
      for (let cutDown = 1; cutDown <= 4; cutDown *= 2) {
        let grown = oldSize * (1 + 0.2 / cutDown);
        grown = Math.min(grown, requestedSize + 100663296);
        const newSize = Math.min(
          maxHeapSize,
          Math.ceil(Math.max(minHeapSize, requestedSize, grown) / PAGE) * PAGE,
        );
        try {
          memory.grow((newSize - memory.buffer.byteLength + PAGE - 1) / PAGE);
          refreshViews();
          return 1;
        } catch {
          // try a smaller growth step
        }
      }
      return 0;
    };
    const imports = {
      a: {
        a: (): never => {
          throw new Error('zopfli exit');
        },
        b: (): number => 0, // _fd_write: zopfli prints nothing in non-verbose mode
        c: (): number => 0, // _fd_seek
        d: (dest: number, src: number, num: number): void => {
          heapU8.copyWithin(dest, src, src + num);
        }, // _emscripten_memcpy_big
        e: resizeHeap,
        f: (): number => 0, // _fd_close
        memory,
        table,
      },
    };
    const { instance } = await WebAssembly.instantiate(wasmBytes, imports);
    const ex = instance.exports as Record<string, (...args: number[]) => number>;
    // The Emscripten glue initialises the heap-top pointer in static memory
    // before running: DYNAMICTOP_PTR = 10624, DYNAMIC_BASE = 5253664.
    heap32[10624 >> 2] = 5253664;
    (ex.g as () => void)(); // __wasm_call_ctors
    const malloc = ex.h;
    const dealloc = ex.i;
    const createOutput = ex.j;
    const getBuffer = ex.k;
    const getBufferSize = ex.l;
    const compress = ex.m;
    zopfli = (input: Uint8Array): Buffer => {
      const ptr = malloc(input.length);
      heapU8.set(input, ptr);
      const out = createOutput();
      // format 1 = zlib, verbose 0, verbose_more 0, 1 iteration, splitting on.
      compress(ptr, input.length, out, 1, 0, 0, ZOPFLI_ITERATIONS, 1, ZOPFLI_BLOCKSPLITTING_MAX);
      const outPtr = getBuffer(out);
      const outSize = getBufferSize(out);
      const result = Buffer.from(heapU8.slice(outPtr, outPtr + outSize));
      dealloc(outPtr);
      dealloc(out);
      dealloc(ptr);
      return result;
    };
  } catch {
    // No Zopfli: the caller falls back to zlib level 9 for every stream.
    zopfli = null;
  }
}

// ---------------------------------------------------------------------------
// PNG codec (written here from the PNG format: signature, chunks, CRC-32,
// the five filters, unfiltering). Only the chunks the checker accepts are
// written: IHDR, PLTE (palette only), tRNS, IDAT (one zlib stream), IEND.
// ---------------------------------------------------------------------------
const PNG_SIGNATURE = Uint8Array.of(137, 80, 78, 71, 13, 10, 26, 10);

const CRC_TABLE: Int32Array = (() => {
  const table = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c;
  }
  return table;
})();

function crc32(bytes: Uint8Array, start = 0, end = bytes.length): number {
  let c = -1;
  for (let i = start; i < end; i++) c = CRC_TABLE[(c ^ bytes[i]) & 0xff] ^ (c >>> 8);
  return (c ^ -1) >>> 0;
}

function pngChunk(type: string, data: Uint8Array): Buffer {
  const out = Buffer.alloc(12 + data.length);
  out.writeUInt32BE(data.length, 0);
  out.write(type, 4, 'ascii');
  Buffer.from(data).copy(out, 8);
  out.writeUInt32BE(crc32(out, 4, 8 + data.length), 8 + data.length);
  return out;
}

function ihdrData(width: number, height: number, colourType: number): Uint8Array {
  const d = new Uint8Array(13);
  const v = new DataView(d.buffer);
  v.setUint32(0, width);
  v.setUint32(4, height);
  d[8] = 8; // bit depth
  d[9] = colourType;
  return d;
}

/** Unfilter one row of `raw` into `out`, given the previous row `prev`. */
function unfilterRow(
  filter: number,
  raw: Uint8Array,
  rawOff: number,
  out: Uint8Array,
  outOff: number,
  prev: Uint8Array | null,
  rowLen: number,
  bpp: number,
): void {
  for (let i = 0; i < rowLen; i++) {
    const x = raw[rawOff + i];
    const left = i >= bpp ? out[outOff + i - bpp] : 0;
    const up = prev !== null ? prev[i] : 0;
    const upLeft = i >= bpp && prev !== null ? prev[i - bpp] : 0;
    let pred = 0;
    if (filter === 1) pred = left;
    else if (filter === 2) pred = up;
    else if (filter === 3) pred = (left + up) >> 1;
    else if (filter === 4) {
      const p = left + up - upLeft;
      const pa = Math.abs(p - left);
      const pb = Math.abs(p - up);
      const pc = Math.abs(p - upLeft);
      pred = pa <= pb && pa <= pc ? left : pb <= pc ? up : upLeft;
    }
    out[outOff + i] = (x + pred) & 0xff;
  }
}

interface DecodedPng {
  width: number;
  height: number;
  colourType: number;
  rgba: Uint8Array; // width * height * 4, unfiltered RGBA samples
}

function readPng(buf: Buffer): DecodedPng {
  if (buf.length < 8 || !PNG_SIGNATURE.every((b, i) => buf[i] === b)) {
    throw new Error('not a PNG');
  }
  let off = 8;
  let width = 0;
  let height = 0;
  let colourType = 6;
  const idat: Buffer[] = [];
  while (off + 8 <= buf.length) {
    const len = buf.readUInt32BE(off);
    const type = buf.toString('ascii', off + 4, off + 8);
    const data = buf.subarray(off + 8, off + 8 + len);
    if (type === 'IHDR') {
      width = data.readUInt32BE(0);
      height = data.readUInt32BE(4);
      colourType = data[9]; // IHDR: bit depth is byte 8, colour type byte 9
    } else if (type === 'IDAT') {
      idat.push(Buffer.from(data));
    } else if (type === 'IEND') {
      break;
    }
    off += 12 + len;
  }
  const channels = colourType === 0 ? 1 : colourType === 2 ? 3 : colourType === 3 ? 1 : colourType === 4 ? 2 : 4;
  const raw = inflateSync(Buffer.concat(idat));
  const rowLen = width * channels;
  const rgba = new Uint8Array(width * height * 4);
  let prev: Uint8Array | null = null;
  const rowBuf = new Uint8Array(rowLen);
  for (let y = 0; y < height; y++) {
    const filter = raw[y * (rowLen + 1)];
    unfilterRow(filter, raw, y * (rowLen + 1) + 1, rowBuf, 0, prev, rowLen, channels);
    prev = rowBuf.slice();
    const dst = y * width * 4;
    if (colourType === 6) {
      rgba.set(rowBuf, dst);
    } else if (colourType === 2) {
      for (let x = 0; x < width; x++) {
        rgba[dst + x * 4] = rowBuf[x * 3];
        rgba[dst + x * 4 + 1] = rowBuf[x * 3 + 1];
        rgba[dst + x * 4 + 2] = rowBuf[x * 3 + 2];
        rgba[dst + x * 4 + 3] = 255;
      }
    } else if (colourType === 0) {
      for (let x = 0; x < width; x++) {
        const g = rowBuf[x];
        rgba[dst + x * 4] = g;
        rgba[dst + x * 4 + 1] = g;
        rgba[dst + x * 4 + 2] = g;
        rgba[dst + x * 4 + 3] = 255;
      }
    } else if (colourType === 4) {
      for (let x = 0; x < width; x++) {
        const g = rowBuf[x * 2];
        rgba[dst + x * 4] = g;
        rgba[dst + x * 4 + 1] = g;
        rgba[dst + x * 4 + 2] = g;
        rgba[dst + x * 4 + 3] = rowBuf[x * 2 + 1];
      }
    } else {
      throw new Error('unsupported input colour type ' + colourType);
    }
  }
  return { width, height, colourType, rgba };
}

// ---------------------------------------------------------------------------
// Filters. A "form" is one colour-type reduction of the RGBA pixels; a
// candidate is one filter strategy over that form's sample bytes.
// ---------------------------------------------------------------------------
function paethPredictor(left: number, up: number, upLeft: number): number {
  const p = left + up - upLeft;
  const pa = Math.abs(p - left);
  const pb = Math.abs(p - up);
  const pc = Math.abs(p - upLeft);
  return pa <= pb && pa <= pc ? left : pb <= pc ? up : upLeft;
}

/** Filter one row with the given filter type; returns the sum of |signed byte|. */
function filterRow(
  filter: number,
  src: Uint8Array,
  srcOff: number,
  dst: Uint8Array,
  dstOff: number,
  prev: Uint8Array | null,
  prevOff: number,
  rowLen: number,
  bpp: number,
): number {
  dst[dstOff] = filter;
  let cost = 0;
  for (let i = 0; i < rowLen; i++) {
    const x = src[srcOff + i];
    const left = i >= bpp ? src[srcOff + i - bpp] : 0;
    const up = prev !== null ? prev[prevOff + i] : 0;
    const upLeft = i >= bpp && prev !== null ? prev[prevOff + i - bpp] : 0;
    let pred = 0;
    if (filter === 1) pred = left;
    else if (filter === 2) pred = up;
    else if (filter === 3) pred = (left + up) >> 1;
    else if (filter === 4) pred = paethPredictor(left, up, upLeft);
    const v = (x - pred) & 0xff;
    dst[dstOff + 1 + i] = v;
    cost += v > 127 ? 256 - v : v;
  }
  return cost;
}

interface FilterCandidate {
  name: string;
  stream: Uint8Array; // height rows of (filter byte + rowLen bytes)
  sumAbs: number; // cheap cost: sum of |signed filtered byte|
}

/** Build one fixed-filter candidate over the whole image. */
function fixedCandidate(
  name: string,
  filter: number,
  data: Uint8Array,
  width: number,
  height: number,
  rowLen: number,
  bpp: number,
): FilterCandidate {
  const stream = new Uint8Array(height * (rowLen + 1));
  let cost = 0;
  for (let y = 0; y < height; y++) {
    const prev = y > 0 ? data.subarray((y - 1) * rowLen, y * rowLen) : null;
    cost += filterRow(filter, data, y * rowLen, stream, y * (rowLen + 1), prev, 0, rowLen, bpp);
  }
  return { name, stream, sumAbs: cost };
}

/**
 * Adaptive candidate: per row, try every filter in `allowed` and keep the one
 * with the smallest sum of |signed byte| (ties: the lowest filter number).
 * `minsum` allows all five filters; `pairs` allows only Up and Paeth.
 */
function adaptiveCandidate(
  name: string,
  allowed: number[],
  data: Uint8Array,
  width: number,
  height: number,
  rowLen: number,
  bpp: number,
): FilterCandidate {
  const stream = new Uint8Array(height * (rowLen + 1));
  // Each trial buffer holds the filter byte plus the row (filterRow writes
  // both); the row bytes are trials[k].subarray(1).
  const trials = allowed.map(() => new Uint8Array(rowLen + 1));
  let totalCost = 0;
  for (let y = 0; y < height; y++) {
    const prev = y > 0 ? data.subarray((y - 1) * rowLen, y * rowLen) : null;
    let bestIdx = 0;
    let bestCost = Infinity;
    for (let k = 0; k < allowed.length; k++) {
      const c = filterRow(allowed[k], data, y * rowLen, trials[k], 0, prev, 0, rowLen, bpp);
      if (c < bestCost) {
        bestCost = c;
        bestIdx = k;
      }
    }
    stream[y * (rowLen + 1)] = allowed[bestIdx];
    stream.set(trials[bestIdx].subarray(1), y * (rowLen + 1) + 1);
    totalCost += bestCost;
  }
  return { name, stream, sumAbs: totalCost };
}

/**
 * Adaptive candidate for grey images: per row, try every filter and keep the
 * one whose (filter byte + filtered row) compresses smallest with zlib level 9.
 * Row-level deflate cost tracks the whole-stream cost better than the
 * sum-of-absolute-values heuristic on grey screenshots.
 */
function deflateRowCandidate(
  name: string,
  data: Uint8Array,
  width: number,
  height: number,
  rowLen: number,
  bpp: number,
): FilterCandidate {
  const stream = new Uint8Array(height * (rowLen + 1));
  // Each trial buffer holds the filter byte plus the row (filterRow writes
  // both); the row bytes are trials[k].subarray(1).
  const trials = [0, 1, 2, 3, 4].map(() => new Uint8Array(rowLen + 1));
  const probe = Buffer.alloc(rowLen + 1);
  let totalCost = 0;
  for (let y = 0; y < height; y++) {
    const prev = y > 0 ? data.subarray((y - 1) * rowLen, y * rowLen) : null;
    let bestIdx = 0;
    let bestCost = Infinity;
    for (let k = 0; k < 5; k++) {
      filterRow(k, data, y * rowLen, trials[k], 0, prev, 0, rowLen, bpp);
      probe[0] = k;
      probe.set(trials[k].subarray(1), 1);
      const c = deflateSync(probe, { level: 9 }).length;
      if (c < bestCost) {
        bestCost = c;
        bestIdx = k;
      }
    }
    stream[y * (rowLen + 1)] = bestIdx;
    stream.set(trials[bestIdx].subarray(1), y * (rowLen + 1) + 1);
    totalCost += bestCost;
  }
  return { name, stream, sumAbs: totalCost };
}

interface Form {
  colourType: number;
  bpp: number; // sample bytes per pixel of this form
  data: Uint8Array; // height * width * bpp unfiltered samples
  palette: Uint8Array | null; // RGB triples for colour type 3
  trns: Uint8Array | null; // alpha per palette entry (type 3) or null
}

/** Reduce RGBA pixels to the smallest applicable colour-type form. */
function chooseForm(rgba: Uint8Array, width: number, height: number): Form {
  const n = width * height;
  let allGrey = true;
  let hasAlpha = false;
  const counts = new Map<number, number>();
  for (let i = 0; i < n; i++) {
    const r = rgba[i * 4];
    const g = rgba[i * 4 + 1];
    const b = rgba[i * 4 + 2];
    const a = rgba[i * 4 + 3];
    if (r !== g || g !== b) allGrey = false;
    if (a !== 255) hasAlpha = true;
    const key = (r << 24) | (g << 16) | (b << 8) | a;
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  if (allGrey) {
    if (!hasAlpha) {
      const data = new Uint8Array(n);
      for (let i = 0; i < n; i++) data[i] = rgba[i * 4];
      return { colourType: 0, bpp: 1, data, palette: null, trns: null };
    }
    const data = new Uint8Array(n * 2);
    for (let i = 0; i < n; i++) {
      data[i * 2] = rgba[i * 4];
      data[i * 2 + 1] = rgba[i * 4 + 3];
    }
    return { colourType: 4, bpp: 2, data, palette: null, trns: null };
  }
  if (counts.size <= 256) {
    // Palette, ordered by pixel count (ties: lower luminance first).
    const entries = [...counts.entries()];
    entries.sort((a, b) => {
      if (b[1] !== a[1]) return b[1] - a[1];
      const la = (((a[0] >>> 24) & 0xff) * 299 + ((a[0] >>> 16) & 0xff) * 587 + ((a[0] >>> 8) & 0xff) * 114) | 0;
      const lb = (((b[0] >>> 24) & 0xff) * 299 + ((b[0] >>> 16) & 0xff) * 587 + ((b[0] >>> 8) & 0xff) * 114) | 0;
      return la - lb;
    });
    const indexOf = new Map<number, number>();
    const palette = new Uint8Array(entries.length * 3);
    const trns = new Uint8Array(entries.length);
    let needTrns = false;
    for (let i = 0; i < entries.length; i++) {
      const key = entries[i][0];
      indexOf.set(key, i);
      palette[i * 3] = (key >>> 24) & 0xff;
      palette[i * 3 + 1] = (key >>> 16) & 0xff;
      palette[i * 3 + 2] = (key >>> 8) & 0xff;
      trns[i] = key & 0xff;
      if ((key & 0xff) !== 255) needTrns = true;
    }
    const data = new Uint8Array(n);
    for (let i = 0; i < n; i++) {
      const key = (rgba[i * 4] << 24) | (rgba[i * 4 + 1] << 16) | (rgba[i * 4 + 2] << 8) | rgba[i * 4 + 3];
      data[i] = indexOf.get(key) as number;
    }
    return { colourType: 3, bpp: 1, data, palette, trns: needTrns ? trns : null };
  }
  if (!hasAlpha) {
    const data = new Uint8Array(n * 3);
    for (let i = 0; i < n; i++) {
      data[i * 3] = rgba[i * 4];
      data[i * 3 + 1] = rgba[i * 4 + 1];
      data[i * 3 + 2] = rgba[i * 4 + 2];
    }
    return { colourType: 2, bpp: 3, data, palette: null, trns: null };
  }
  return { colourType: 6, bpp: 4, data: rgba.slice(), palette: null, trns: null };
}

function buildCandidates(form: Form, width: number, height: number): FilterCandidate[] {
  const rowLen = width * form.bpp;
  const out: FilterCandidate[] = [];
  for (let f = 0; f <= 4; f++) {
    out.push(fixedCandidate('f' + f, f, form.data, width, height, rowLen, form.bpp));
  }
  out.push(adaptiveCandidate('minsum', [0, 1, 2, 3, 4], form.data, width, height, rowLen, form.bpp));
  out.push(adaptiveCandidate('pairs', [2, 4], form.data, width, height, rowLen, form.bpp));
  if (form.colourType === 0) {
    out.push(deflateRowCandidate('zlib9row', form.data, width, height, rowLen, form.bpp));
  }
  return out;
}

function writePng(form: Form, width: number, height: number, zlibStream: Uint8Array): Buffer {
  const chunks: Buffer[] = [pngChunk('IHDR', ihdrData(width, height, form.colourType))];
  if (form.colourType === 3 && form.palette !== null) {
    chunks.push(pngChunk('PLTE', form.palette));
    if (form.trns !== null) chunks.push(pngChunk('tRNS', form.trns));
  }
  chunks.push(pngChunk('IDAT', zlibStream));
  chunks.push(pngChunk('IEND', new Uint8Array(0)));
  return Buffer.concat([Buffer.from(PNG_SIGNATURE), ...chunks]);
}

// ---------------------------------------------------------------------------
// Main: two phases. Phase A picks each instance's winning filtered stream
// (zlib-6 ranking over all candidates, then zlib-9 over the top 3). Phase B
// hands the smallest streams to Zopfli up to the cumulative budget and
// compresses the rest with zlib level 9. An unfiltered multi-byte stream is
// slow for Zopfli, so for those Zopfli gets the best filtered stream instead
// (only when it is close by level-6 size, else no Zopfli for that instance).
// Nothing here reads the clock.
// ---------------------------------------------------------------------------
interface Winner {
  id: string;
  form: Form;
  width: number;
  height: number;
  stream: Uint8Array;
  zlib9: Buffer; // the winner stream compressed with zlib level 9
  name: string; // the winning candidate's name ('f0'..'f4', 'minsum', 'pairs', 'zlib9row')
  l6: number; // the winner's zlib level-6 size
  bestFiltered: FilterCandidate | null; // smallest level-6 non-'f0' candidate, if any
  bestFilteredL6: number;
}

const INPUT_DIR = process.env.MAKEFUN_INPUT_DIR ?? '/input';
const OUTPUT_DIR = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';

async function main(): Promise<void> {
  await initZopfli();
  const ids = readdirSync(INPUT_DIR).sort();
  const winners: Winner[] = [];
  for (const id of ids) {
    const png = readPng(readFileSync(join(INPUT_DIR, id, 'image.png')));
    const form = chooseForm(png.rgba, png.width, png.height);
    const candidates = buildCandidates(form, png.width, png.height);
    // Rank every candidate by its real zlib level-6 size: the cheap
    // sum-of-absolute-values cost is misleading here (on this data the
    // unfiltered stream often deflates best), and level 1 misranks too.
    // Level 6 tracks level 9 closely, so the top 3 go to a level-9 final.
    const ranked = candidates
      .map((cand) => ({ cand, l6: deflateSync(cand.stream, { level: 6 }).length }))
      .sort((a, b) => a.l6 - b.l6 || (a.cand.name < b.cand.name ? -1 : 1));
    const shortlist = ranked.slice(0, 3);
    let best: FilterCandidate | null = null;
    let bestZlib: Buffer | null = null;
    let bestL6 = 0;
    for (const { cand, l6 } of shortlist) {
      const z = deflateSync(cand.stream, { level: 9 });
      if (best === null || z.length < (bestZlib as Buffer).length) {
        best = cand;
        bestZlib = z;
        bestL6 = l6;
      }
    }
    // The best filtered (non-'f0') candidate, for the Zopfli-input rule below.
    let bestFiltered: FilterCandidate | null = null;
    let bestFilteredL6 = Infinity;
    for (const { cand, l6 } of ranked) {
      if (cand.name !== 'f0' && l6 < bestFilteredL6) {
        bestFiltered = cand;
        bestFilteredL6 = l6;
      }
    }
    winners.push({
      id,
      form,
      width: png.width,
      height: png.height,
      stream: (best as FilterCandidate).stream,
      zlib9: bestZlib as Buffer,
      name: (best as FilterCandidate).name,
      l6: bestL6,
      bestFiltered,
      bestFilteredL6,
    });
  }
  // Zopfli goes to the smallest winning streams first, up to the budget.
  const order = [...winners].sort((a, b) => a.stream.length - b.stream.length || (a.id < b.id ? -1 : 1));
  const useZopfli = new Set<Winner>();
  let spent = 0;
  for (const w of order) {
    if (zopfli !== null && spent + w.stream.length <= ZOPFLI_BUDGET_BYTES) {
      useZopfli.add(w);
      spent += w.stream.length;
    }
  }
  for (const w of winners) {
    let zlibStream: Buffer = w.zlib9;
    if (useZopfli.has(w) && zopfli !== null) {
      // Which stream Zopfli compresses: the winner, except an unfiltered
      // multi-byte-per-pixel stream is slow for Zopfli (long flat runs give
      // it far too many matches to price). For those, feed it the best
      // filtered stream instead, but only when that stream is close to the
      // winner by level-6 size; otherwise Zopfli is skipped for the
      // instance entirely and the zlib-9 winner stands.
      let input: Uint8Array | null = w.stream;
      if (w.name === 'f0' && w.form.bpp >= 3) {
        if (w.bestFiltered !== null && w.bestFilteredL6 <= 1.1 * w.l6) {
          input = w.bestFiltered.stream;
        } else {
          input = null;
        }
      }
      if (input !== null) {
        const z = zopfli(input);
        if (z.length < zlibStream.length) zlibStream = z;
      }
    }
    const out = writePng(w.form, w.width, w.height, zlibStream);
    mkdirSync(join(OUTPUT_DIR, w.id), { recursive: true });
    writeFileSync(join(OUTPUT_DIR, w.id, 'image.png'), out);
  }
}

main().catch((err) => {
  // A failed instance must not take the whole set down silently: rethrow so
  // the harness records the failure instead of scoring a partial set.
  throw err;
});
